var WordData=(function(){
  var MS=86400000;

  function pad(n){return (n<10?'0':'')+n}

  /* 그날 말씀은 새벽 다섯 시(한국시간)에 열린다.
     그 전에는 아직 어제 말씀을 읽는 때다 — 밤 열두 시가 넘었다고
     다음 날 말씀이 미리 열리지는 않는다.
     기기 시계가 어느 나라에 맞춰져 있든 한국 시각으로 따진다. */
  var OPEN_HOUR = 5;

  function kstNow(){
    var n = new Date();
    try {
      var f = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Seoul',
        year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', hour12: false });
      var o = {};
      f.formatToParts(n).forEach(function (p) { o[p.type] = p.value; });
      if (o.year && o.month && o.day && o.hour != null) {
        return { y: +o.year, m: +o.month, d: +o.day, h: (+o.hour) % 24 };
      }
    } catch (e) { /* 시간대를 모르는 낡은 브라우저 */ }
    var k = new Date(n.getTime() + n.getTimezoneOffset() * 60000 + 9 * 3600000);
    return { y: k.getFullYear(), m: k.getMonth() + 1, d: k.getDate(), h: k.getHours() };
  }

  /* 지금 열려 있는 말씀의 날짜 */
  function today(){
    var k = kstNow();
    var ds = k.y + '-' + pad(k.m) + '-' + pad(k.d);
    return k.h < OPEN_HOUR ? shift(ds, -1) : ds;
  }

  /* 아직 열리지 않은 날인가 */
  function locked(ds){ return String(ds) > today(); }
  /* 묵상집은 시리즈 첫날 새벽(OPEN_HOUR)에 열린다 */
  function bookOpen(){ return typeof WORD_SERIES === 'undefined' || today() >= WORD_SERIES.from; }
  function dayIndex(ds){var p=String(ds).split('-');return Math.floor(Date.UTC(+p[0],+p[1]-1,+p[2])/MS)}
  function shift(ds,n){var d=new Date((dayIndex(ds)+n)*MS);return d.getUTCFullYear()+'-'+pad(d.getUTCMonth()+1)+'-'+pad(d.getUTCDate())}
  function weekday(ds){return ['주일','월','화','수','목','금','토'][new Date(dayIndex(ds)*MS).getUTCDay()]}

  /* "사무엘상 17:41-50"  → {book,chapter,from,toChapter,to}
     "사무엘상 3:19-4:11" 처럼 장을 넘어가는 것도 읽는다.
     chapter/toChapter 는 시작 장과 끝 장, from/to 는 그 장 안의 절 번호다. */
  function parseRef(passage){
    var m=String(passage||'').match(/^\s*(.+?)\s+(\d+)\s*:\s*(\d+)(?:\s*-\s*(?:(\d+)\s*:\s*)?(\d+))?/);
    if(!m)return null;
    var c1=parseInt(m[2],10), v1=parseInt(m[3],10);
    var c2=m[4]?parseInt(m[4],10):c1;
    var v2=m[5]?parseInt(m[5],10):v1;
    return {book:m[1].trim(),chapter:String(c1),from:v1,toChapter:String(c2),to:v2};
  }

  /* 본문이 걸치는 (장, 시작절, 끝절) 을 차례로 돌려준다 */
  function refSpans(r,bk){
    var out=[],c1=parseInt(r.chapter,10),c2=parseInt(r.toChapter||r.chapter,10);
    for(var c=c1;c<=c2;c++){
      var ch=bk&&bk.data&&bk.data[String(c)];
      if(!ch)continue;
      var last=1;for(var k in ch){var n=parseInt(k,10);if(n>last)last=n}
      out.push({chapter:String(c),from:c===c1?r.from:1,to:c===c2?r.to:last});
    }
    return out;
  }

  function cycleFor(ds){return WORD_CYCLE[((dayIndex(ds)%WORD_CYCLE.length)+WORD_CYCLE.length)%WORD_CYCLE.length]}

  /* 계획 본문(어린이 콘텐츠가 없는 날)을 위한 자동 구성 */
  function kidsFromPlan(ds,info){
    var i=((dayIndex(ds)%KID_MISSIONS.length)+KID_MISSIONS.length)%KID_MISSIONS.length;
    var j=((dayIndex(ds)%KID_QUIZ_POOL.length)+KID_QUIZ_POOL.length)%KID_QUIZ_POOL.length;
    var k=((dayIndex(ds)%KID_EMOJI.length)+KID_EMOJI.length)%KID_EMOJI.length;
    var r=parseRef(info.passage);
    var qz=KID_QUIZ_POOL[j];
    return {
      verseRef: r? (r.book+' '+r.chapter+':'+r.from) : info.passage,
      emoji: KID_EMOJI[k],
      summary: '오늘은 「'+info.title+'」 이야기예요. 말씀을 읽으면서 하나님이 어떤 분이신지 찾아보아요.',
      mission: KID_MISSIONS[i],
      quiz: {q:qz.q,c:qz.c.slice(),a:qz.a},
      auto: true
    };
  }

  function adultFromPlan(info){
    return {
      questions:[
        '오늘 본문에서 하나님은 어떤 분으로 나타나십니까?',
        '이 말씀이 오늘 나의 어떤 자리를 만지고 있습니까?',
        '내가 한 가지 순종한다면 무엇이겠습니까?'
      ],
      prayer:'주님, 오늘 「'+info.title+'」의 말씀으로 저를 빚어 주십시오.'
    };
  }

  /* 하루치 말씀 — custom(관리자 지정) > plan(교회 읽기표) > cycle(큐레이션) */
  function forDate(ds,custom){
    ds=ds||today();
    var c=custom&&custom[ds];
    if(c&&c.passage){
      var base={date:ds,passage:c.passage,title:c.title||c.passage,theme:c.theme||'',source:'custom'};
      base.adult=adultFromPlan(base);
      base.kids=kidsFromPlan(ds,base);
      if(c.kidSummary)base.kids.summary=c.kidSummary;
      if(c.kidMission)base.kids.mission=c.kidMission;
      if(c.kidSummary||c.kidMission)base.kids.auto=false;
      return base;
    }
    var info=WORD_PLAN[ds];
    if(info&&info.passage){
      var o={date:ds,passage:info.passage,title:info.title||info.passage,theme:info.week_theme||info.theme||'',source:'plan',explain:info.ex||'',
             tq:info.tq||'',hook:info.hook||null,gospel:info.gs||'',remember:info.mm||'',
             feast:info.sd||'',kidPrayer:info.kp||'',youth:info.yq?{q:info.yq,a:info.ya||''}:null};
      /* 읽기표가 묵상·어린이 콘텐츠를 함께 담고 있으면 그것을 쓰고, 없으면 자동 구성한다 */
      o.adult=(info.qs&&info.pr)?{questions:info.qs.slice(),prayer:info.pr}:adultFromPlan(o);
      if(info.ks){
        o.kids={verseRef:info.kv||o.passage,emoji:info.e||'📖',summary:info.ks,mission:info.m||KID_MISSIONS[0],
                quiz:info.q?{q:info.q,c:info.c.slice(),a:info.a}:kidsFromPlan(ds,o).quiz,auto:false};
      }else{
        o.kids=kidsFromPlan(ds,o);
      }
      return o;
    }
    var e=cycleFor(ds);
    return {
      date:ds,passage:e.p,title:e.t,theme:e.th,source:'cycle',
      adult:{questions:e.qs.slice(),prayer:e.pr},
      kids:{verseRef:e.kv,emoji:e.e,summary:e.ks,mission:e.m,quiz:{q:e.q,c:e.c.slice(),a:e.a},auto:false}
    };
  }

  /* 달력/목록용 — 해당 달의 모든 날 */
  function monthList(ym,custom){
    var p=ym.split('-'),y=+p[0],mo=+p[1];
    var last=new Date(Date.UTC(y,mo,0)).getUTCDate(),out=[];
    for(var d=1;d<=last;d++)out.push(forDate(y+'-'+pad(mo)+'-'+pad(d),custom));
    return out;
  }

  function recent(n,ds,custom){
    ds=ds||today();var out=[];
    for(var i=0;i<n;i++)out.push(forDate(shift(ds,-i),custom));
    return out;
  }

  /* 주제 시리즈 안의 날이면 시리즈 이름과 몇째 날·몇째 주인지 알려 준다 (WORD_SERIES 는 파일 끝에서 정의) */
  function series(ds){
    var S=(typeof WORD_SERIES!=='undefined')?WORD_SERIES:null;
    ds=ds||today();
    if(!S||ds<S.from||ds>S.to)return null;
    var w=null,wi=-1;
    for(var i=0;i<S.weeks.length;i++){if(S.weeks[i].mon<=ds){w=S.weeks[i];wi=i}}
    return {id:S.id,title:S.title,sub:S.sub,day:dayIndex(ds)-dayIndex(S.from)+1,
            total:dayIndex(S.to)-dayIndex(S.from)+1,week:w,weekNo:wi+1,weeks:S.weeks};
  }

  return {today:today,locked:locked,bookOpen:bookOpen,openHour:OPEN_HOUR,pad:pad,dayIndex:dayIndex,shift:shift,weekday:weekday,
          parseRef:parseRef,refSpans:refSpans,forDate:forDate,monthList:monthList,recent:recent,series:series};
})();

if(typeof module!=='undefined'&&module.exports)module.exports={WORD_CYCLE:WORD_CYCLE,WORD_PLAN:WORD_PLAN,WordData:WordData};

